export declare const GROUPED_VIEW_CSS = "\n:host {\n  display: block;\n  font-family: var(--pages-font-family, system-ui, sans-serif);\n  font-size: var(--pages-font-size-base, 14px);\n  color: var(--pages-neutral-12, #333);\n}\n\n/* Shared column header bar */\n.column-header-bar {\n  display: grid;\n  position: sticky;\n  top: 0;\n  z-index: 1;\n  background: var(--pages-neutral-1, #fff);\n  border-bottom: 2px solid var(--pages-neutral-5, #ddd);\n}\n\n.col-header {\n  background: none;\n  border: none;\n  cursor: pointer;\n  text-align: left;\n  padding: var(--pages-space-2, 8px) var(--pages-space-3, 12px);\n  font-weight: var(--pages-font-weight-semibold, 600);\n  font-size: var(--pages-font-size-sm, 12px);\n  color: var(--pages-neutral-9, #666);\n  white-space: nowrap;\n  display: flex;\n  align-items: center;\n  gap: var(--pages-space-1, 4px);\n}\n\n.col-header:hover {\n  color: var(--pages-neutral-12, #333);\n}\n\n.col-header.sort-asc::after { content: \" \u25B2\"; font-size: 10px; }\n.col-header.sort-desc::after { content: \" \u25BC\"; font-size: 10px; }\n\n.col-label {\n  text-align: left;\n  padding: var(--pages-space-2, 8px) var(--pages-space-3, 12px);\n  font-weight: var(--pages-font-weight-semibold, 600);\n  font-size: var(--pages-font-size-sm, 12px);\n  color: var(--pages-neutral-9, #666);\n  white-space: nowrap;\n}\n\n/* Sectioned mode \u2014 section headings */\n.section-toggle {\n  font-size: var(--pages-font-size-lg, 18px);\n  font-weight: var(--pages-font-weight-semibold, 600);\n  color: var(--pages-neutral-12, #333);\n  background: none;\n  border: none;\n  padding: var(--pages-space-3, 12px) 0 var(--pages-space-2, 8px);\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  gap: var(--pages-space-2, 8px);\n  width: 100%;\n}\n\n.section-chevron {\n  font-size: var(--pages-font-size-sm, 12px);\n  transition: transform var(--pages-duration-fast, 150ms) var(--pages-ease-default, ease);\n  display: inline-block;\n}\n\n.section-chevron.expanded {\n  transform: rotate(90deg);\n}\n\n.section-summary {\n  font-size: var(--pages-font-size-sm, 12px);\n  font-weight: var(--pages-font-weight-normal, 400);\n  color: var(--pages-neutral-8, #888);\n  margin-left: var(--pages-space-2, 8px);\n}\n\n.section-content {\n  overflow: hidden;\n}\n\n/* Depth-based sub-section styling for multi-level grouping */\n.sub-section-toggle {\n  font-size: var(--pages-font-size-base, 14px);\n  font-weight: var(--pages-font-weight-semibold, 600);\n  color: var(--pages-neutral-10, #555);\n  background: none;\n  border: none;\n  padding: var(--pages-space-2, 8px) 0;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  gap: var(--pages-space-2, 8px);\n  width: 100%;\n  border-bottom: 1px solid var(--pages-neutral-4, #e5e5e5);\n}\n\n/* Spreadsheet mode \u2014 compact group headers */\n.group-toggle {\n  background: var(--pages-neutral-3, #f5f5f5);\n  border: none;\n  border-bottom: 1px solid var(--pages-neutral-5, #ddd);\n  cursor: pointer;\n  font: inherit;\n  font-weight: var(--pages-font-weight-semibold, 600);\n  font-size: var(--pages-font-size-sm, 12px);\n  color: var(--pages-neutral-12, #333);\n  padding: var(--pages-space-2, 8px) var(--pages-space-3, 12px);\n  display: flex;\n  align-items: center;\n  gap: var(--pages-space-2, 8px);\n  width: 100%;\n}\n\n.group-chevron {\n  font-size: var(--pages-font-size-xs, 10px);\n}\n\n.spreadsheet .group-section {\n  margin: 0;\n}\n\n.spreadsheet .section-content {\n  margin: 0;\n  padding: 0;\n}\n\n/* Embedded pages-table overrides */\n.section-content pages-table {\n  display: block;\n}\n\n.aligned-list {\n  display: grid;\n  row-gap: 0;\n  padding: 0 var(--pages-space-3, 12px);\n}\n\n.list-item {\n  display: contents;\n}\n\n.list-item dd {\n  margin: 0;\n  padding: var(--pages-space-1, 4px) var(--pages-space-2, 8px);\n  color: var(--pages-neutral-11, #444);\n}\n\n.list-item + .list-item dd {\n  border-top: 1px solid var(--pages-neutral-3, #eee);\n}\n\n.visually-hidden {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  margin: -1px;\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n  white-space: nowrap;\n  border: 0;\n}\n\n/* Column picker */\n.column-picker-wrapper {\n  position: relative;\n  margin-left: auto;\n}\n\n.column-picker-trigger {\n  background: none;\n  border: 1px solid var(--pages-neutral-6, #9e9e9e);\n  border-radius: 4px;\n  cursor: pointer;\n  font-size: 16px;\n  padding: 2px 6px;\n  line-height: 1;\n}\n\n.column-picker-dropdown {\n  position: absolute;\n  right: 0;\n  top: 100%;\n  background: var(--pages-neutral-1, #fff);\n  border: 1px solid var(--pages-neutral-6, #9e9e9e);\n  border-radius: 4px;\n  padding: 8px;\n  z-index: 10;\n  min-width: 160px;\n  box-shadow: 0 2px 8px rgba(0,0,0,0.15);\n}\n\n.picker-section-label {\n  font-size: 11px;\n  font-weight: 600;\n  text-transform: uppercase;\n  color: var(--pages-neutral-9, #616161);\n  margin-bottom: 4px;\n}\n\n.column-picker-item {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 2px 0;\n  cursor: pointer;\n  font-size: 13px;\n}\n\n.column-picker-item input[disabled] {\n  opacity: 0.4;\n  cursor: not-allowed;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .section-content,\n  .section-chevron {\n    transition: none !important;\n  }\n}\n";
